<?php
// Appended after the original rate suite on its exact disposable schema.
require_once $root.'/phpBB2/ctracker/classes/class_contact_rate_storage.php';
function cr_hash($id='client-a'){return ctracker_rate_arguments('contact-cooldown',$id);}
function cr_row($id='client-a'){return rate_rows('SELECT window_start,request_count,updated_at FROM '.CTRACKER_RATE_LIMITS." WHERE bucket_hash='".cr_hash($id)."'");}
function cr_snapshot(){return rate_rows('SELECT * FROM '.CTRACKER_RATE_LIMITS.' ORDER BY bucket_hash');}
function cr_reset(){rate_reset();foreach(glob($GLOBALS['cr_dir'].'/contact-*.rate')as$file){if(is_file($file)){unlink($file);}elseif(is_dir($file)){rmdir($file);}}}
function cr_call($id='client-a',$interval=60){return rate_call('contact',array($GLOBALS['cr_dir'],$id,$interval));}
function cr_create(){global$root;$schema=file_get_contents($root.'/phpBB2/install/schemas/mysql_schema.sql');
	if(!function_exists('update_extract_create_tables')){$updater=file_get_contents($root.'/update/update_from_153a.php');$start=strpos($updater,'function update_extract_create_tables(');$end=strpos($updater,'function update_extract_seed_statements(',$start);rate_check($start!==false&&$end!==false,'Actual updater parser boundary');eval(substr($updater,$start,$end-$start));}
	$definitions=update_extract_create_tables($schema);rate_check(isset($definitions['phpbb_ctracker_rate_limits']),'Existing updater creates the exact participant');require_once $root.'/update/innodb_migration.php';rate_check(in_array(CTRACKER_RATE_LIMITS,plus_storage_tables($schema,'fixture_'),true),'Existing canonical migration covers contact participant');rate_sql(str_replace('phpbb_ctracker_rate_limits',CTRACKER_RATE_LIMITS,$definitions['phpbb_ctracker_rate_limits']));}
function cr_suite(){
	global$root,$db,$rate_root,$rate_peer,$rate_hook,$rate_factory,$rate_queries,$host,$password,$fixture,$cr_dir;
	cr_create();$cr_dir=false;for($i=0;$i<100;$i++){$candidate=sys_get_temp_dir().'/phpbb-contact-rate-'.getmypid().'-'.$i;if(@mkdir($candidate,0700)){$cr_dir=$candidate;break;}}rate_check($cr_dir!==false,'Own legacy cache fixture');$cases=1;$faults=0;
	try{
		cr_reset();rate_check(cr_call()===true&&cr_call()===false,'First claim and immediate denial');$before=cr_snapshot();rate_check(cr_call()===false&&cr_snapshot()===$before,'Denied attempts do not renew cooldown or count');$cases+=2;
		rate_check(cr_call('client-b')===true&&count(cr_snapshot())===2,'Independent senders');$cases++;
		rate_check((float)cr_row()[0]['window_start']-(float)cr_row()[0]['updated_at']===2419200.0,'Shared cleanup retains the original thirty-day contact history');$cases++;
		cr_reset();rate_check(rate_call('contact',array($cr_dir.'/not-present','no-cache',60))===true&&!file_exists($cr_dir.'/not-present'),'No writable cache dependency or new files');$cases++;
		cr_reset();rate_check(cr_call('client-a',2147483647)===true&&(float)cr_row()[0]['window_start']>2147483647&&cr_call('client-a',2147483647)===false,'Full existing flood range without signed overflow');$cases++;
		foreach(array('expired','future','saturated','long-window')as$kind){cr_reset();$stamp=time()+($kind==='future'?600:($kind==='long-window'?-200000:-120));$interval=$kind==='long-window'?300000:60;rate_seed(cr_hash(),sprintf('%.0f',(float)$stamp+$interval),$kind==='saturated'?'4294967295':'3',$stamp);$before=cr_row();$out=cr_call('client-a',$interval);rate_check($out===in_array($kind,array('expired','saturated'),true),'Current sliding cooldown: '.$kind);$after=cr_row();if(!$out){rate_check($after===$before,'No shortening future/long cooldown');}else{rate_check((float)$after[0]['updated_at']>=$stamp+60&&($kind!=='saturated'||$after[0]['request_count']==='4294967295'),'Fresh acknowledged timestamp and safe saturation');}$cases++;}
		foreach(array('active','expired','empty','malformed','overflow','oversized')as$kind){cr_reset();$file=$cr_dir.'/contact-'.hash('sha256','client-a').'.rate';$value=$kind==='active'?(string)time():($kind==='expired'?(string)(time()-120):($kind==='empty'?'':($kind==='malformed'?'old broken marker':($kind==='overflow'?'4294967295':str_repeat('1',33)))));file_put_contents($file,$value);$out=cr_call();rate_check($out===in_array($kind,array('expired','empty','malformed'),true)&&file_get_contents($file)===$value,'Exact read-only legacy handoff: '.$kind);if($kind==='active'){rate_check(cr_row()[0]['updated_at']===$value,'Active file seeded in existing canonical table');unlink($file);rate_check(cr_call()===false,'Migrated active cooldown survives legacy-file removal');}$cases++;}
		cr_reset();$file=$cr_dir.'/contact-'.hash('sha256','client-a').'.rate';file_put_contents($file,(string)(time()-120));rate_seed(cr_hash(),time()+2419200,1,time());$before=cr_row();rate_check(cr_call()===false&&cr_row()===$before,'Older legacy stamp cannot roll back newer DB claim');$cases++;
		cr_reset();$file=$cr_dir.'/contact-'.hash('sha256','client-a').'.rate';mkdir($file);rate_check(cr_call()===false&&!cr_snapshot(),'Non-file legacy path fails closed before claim');rmdir($file);$cases++;
		cr_reset();$file=$cr_dir.'/contact-'.hash('sha256','client-a').'.rate';file_put_contents($file,(string)(time()-120));$held=fopen($file,'r+b');rate_check(flock($held,LOCK_EX|LOCK_NB),'Own legacy writer lock');try{rate_check(cr_call()===false&&!cr_snapshot(),'Busy legacy writer is never read partially');$cases++;}finally{flock($held,LOCK_UN);fclose($held);}
		foreach(array('missing','borrow','alias','busy','autocommit','foreign')as$factory){cr_reset();$rate_factory=$factory;$rate_root->sql_query('START TRANSACTION');$rate_root->sql_query('UPDATE fixture_rate_caller SET marker=8 WHERE id=1');if($factory==='busy'){rate_sql('START TRANSACTION');rate_sql('UPDATE fixture_rate_caller SET marker=9 WHERE id=2');}try{rate_check(cr_call()===false&&!cr_snapshot(),'Reject unsuitable factory: '.$factory);$r=$rate_root->sql_query('SELECT marker FROM fixture_rate_caller WHERE id=1');$row=$rate_root->sql_fetchrow($r);$rate_root->sql_freeresult($r);rate_check($row['marker']==='8'&&$rate_root->db_connect_id&&$rate_peer->db_connect_id,'Preserve caller and borrower');$cases++;}finally{$rate_factory='normal';$rate_root->sql_query('ROLLBACK');if($factory==='busy'){rate_sql('ROLLBACK');}}}
		cr_reset();$rate_root->sql_query('START TRANSACTION');$rate_root->sql_query('UPDATE fixture_rate_caller SET marker=8 WHERE id=1');try{rate_check(cr_call()===true,'Ordinary independent caller claim');}finally{$rate_root->sql_query('ROLLBACK');}rate_check(cr_call()===false,'Caller rollback cannot erase committed cooldown');$cases++;
		foreach(array('engine','key','signed','nullable')as$kind){cr_reset();$ddl=$kind==='engine'?'ENGINE=MyISAM':($kind==='key'?'DROP PRIMARY KEY':($kind==='signed'?'MODIFY request_count INT NOT NULL DEFAULT0':'MODIFY updated_at INT UNSIGNED NULL'));$ddl=str_replace('DEFAULT0','DEFAULT 0',$ddl);rate_sql('ALTER TABLE '.CTRACKER_RATE_LIMITS.' '.$ddl);try{rate_check(cr_call()===false&&!cr_snapshot(),'Canonical participant required: '.$kind);$cases++;}finally{rate_sql('DROP TABLE '.CTRACKER_RATE_LIMITS);cr_create();}}
		cr_reset();rate_seed(strtoupper(cr_hash()),0,0,0);$before=cr_snapshot();rate_check(cr_call()===false&&cr_snapshot()===$before,'Case drift cannot be silently reused');$cases++;
		foreach(array('','STRICT_TRANS_TABLES,NO_BACKSLASH_ESCAPES','ANSI_QUOTES','TRADITIONAL')as$mode){cr_reset();$fired=false;$rate_hook=function($phase,$sql,$owner)use($mode,&$fired){if(!$fired&&$phase==='before'&&strpos($sql,'SET SESSION sql_mode=')===0){$fired=true;$owner->connection->sql_query("SET SESSION sql_mode='$mode'");}};rate_check(cr_call()===true&&$fired,'Actual SQL mode compatibility');$rate_hook=null;$cases++;}
		// Every actual owner query may fail before/after, including lost COMMIT
		// acknowledgement. No failed decision is allowed to send or retry itself.
		cr_reset();$rate_queries=array();rate_check(cr_call()===true,'Successful owner trace');$trace=$rate_queries;
		foreach($trace as$position=>$statement){foreach(array('before','after')as$phase){cr_reset();$seen=0;$hit=false;$rate_hook=function($event,$sql)use($position,$phase,&$seen,&$hit){if($event==='before'){$seen++;}if($event===$phase&&$seen===$position+1){$hit=true;return false;}};$out=cr_call();$rate_hook=null;rate_check($hit&&$out===false,'Every SQL/commit failure refuses acknowledged claim');$stored=cr_snapshot();rate_check($statement==='COMMIT'&&$phase==='after'?count($stored)===1:!$stored,'Exact rollback or uncertain completed claim');$faults++;}}
		cr_reset();$drift=false;$rate_hook=function($phase,$sql,$owner)use(&$drift){if(!$drift&&$phase==='after'&&strpos($sql,'INSERT INTO ')===0&&strpos($sql,'window_start=VALUES(window_start)')!==false){$drift=true;$owner->connection->sql_query('DELETE FROM '.CTRACKER_RATE_LIMITS);}};rate_check(cr_call()===false&&$drift&&!cr_snapshot(),'Actual own readback drift rolls back');$rate_hook=null;$cases++;
		// The real shared collector cannot remove a row being renewed, and its
		// ordinary predicate no longer matches once renewal has committed.
		cr_reset();$old=time()-200000;rate_seed(cr_hash(),$old,1,$old);$blocked=false;$rate_hook=function($phase,$sql)use(&$blocked,$rate_root){if($phase==='after'&&strpos($sql,'SELECT window_start,request_count,updated_at')===0){$GLOBALS['rate_hook']=null;$gc=new CtrackerRateScope($rate_root,true);try{$gc->commit();try{$gc->collect(time());}catch(CtrackerRateStorageException$error){$blocked=true;}}finally{$gc->release();}}};rate_check(cr_call()===true&&$blocked,'Real collector waits on the owned contact row');$rate_hook=null;$gc=new CtrackerRateScope($rate_root,true);try{$gc->commit();$gc->collect(time());}finally{$gc->release();}rate_check(count(cr_row())===1&&cr_call()===false,'Actual post-commit collector preserves renewed cooldown');$cases++;
		cr_reset();$stamp=time()-200000;rate_seed(cr_hash(),$stamp+300000,1,$stamp);$gc=new CtrackerRateScope($rate_root,true);try{$gc->commit();$gc->collect(time());}finally{$gc->release();}rate_check(count(cr_row())===1&&cr_call('client-a',300000)===false,'Long configured intervals survive shared GC');$cases++;
		cr_reset();$stamp=time()-604800;rate_seed(cr_hash(),$stamp+2419200,1,$stamp);$gc=new CtrackerRateScope($rate_root,true);try{$gc->commit();$gc->collect(time());}finally{$gc->release();}rate_check(count(cr_row())===1&&cr_call('client-a',864000)===false,'Increasing the configured interval retains recent sender history');$cases++;
		// Four real PHP processes on the same canonical schema and identity.
		cr_reset();$worker=$cr_dir.'/worker.php';$worker_code='<?php define("IN_PHPBB",true);define("CTRACKER_RATE_LIMITS",'.var_export(CTRACKER_RATE_LIMITS,true).');$root='.var_export($root.'/phpBB2/',true).';require$root."includes/php_compat.php";require$root."db/mysqli.php";require$root."ctracker/classes/class_contact_rate_storage.php";$db=new sql_db('.var_export($host,true).',"root",'.var_export($password,true).','.var_export($fixture,true).',false);try{echo ctracker_rate_limit_contact('.var_export($cr_dir,true).',"parallel",60)?"1":"0";}finally{$db->sql_close();}';file_put_contents($worker,$worker_code);
		$options=DIRECTORY_SEPARATOR==='\\'?' -n -d extension_dir='.escapeshellarg(ini_get('extension_dir')).' -d extension=php_mysqli.dll -d extension=php_openssl.dll':'';$command=escapeshellarg(PHP_BINARY).$options.' -d date.timezone=UTC -d disable_functions=mail '.escapeshellarg($worker);$children=array();for($i=0;$i<4;$i++){$pipes=array();$process=proc_open($command,array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w')),$pipes,null,null,array('bypass_shell'=>true));rate_check(is_resource($process),'Real worker started');fclose($pipes[0]);$children[]=array($process,$pipes);}$accepted=0;foreach($children as$child){$out=stream_get_contents($child[1][1]);$err=stream_get_contents($child[1][2]);fclose($child[1][1]);fclose($child[1][2]);$exit=proc_close($child[0]);rate_check($exit===0&&$err===''&&in_array($out,array('0','1'),true),'Actual worker completes without warnings: '.json_encode(array($exit,$out,$err)));$accepted+=(int)$out;}unlink($worker);rate_check($accepted===1&&count(cr_row('parallel'))===1&&cr_row('parallel')[0]['request_count']==='1','Exactly one parallel claim is acknowledged');$cases++;
		cr_reset();$rate_queries=array();rate_check(rate_call('contact',array($cr_dir,'',60))===false&&rate_call('contact',array($cr_dir,'ip',array()))===false&&!$rate_queries,'Invalid input rejected before SQL');$cases++;
		cr_reset();rate_sql('DROP TABLE '.CTRACKER_RATE_LIMITS);try{rate_check(cr_call()===false,'Missing participant refuses delivery');$cases++;}finally{cr_create();}
		echo 'Native contact cooldown: '.$cases.' cases, '.$faults." SQL faults, 4 real workers PASS; canonical atomic sliding claims, read-only legacy handoff, isolated callers, honest ACK and renewal-safe shared GC.\n";
	}finally{$rate_hook=null;cr_reset();if(is_file($cr_dir.'/worker.php')){unlink($cr_dir.'/worker.php');}rmdir($cr_dir);}
}
cr_suite();
